def fingerprint(text):
    """As the toolkit's (wsp.data.fingerprint): lower case, letters and digits only, sha1, first 16 hex."""
    return hashlib.sha1(re.sub(r"[^a-z0-9]+", " ", text.lower()).strip().encode()).hexdigest()[:16]


def opts(rng, right, wrong, n=None, shuffle=True):
    """Options block "(A) x" ... and the label of the right one."""
    wrong = [w for w in dict.fromkeys(wrong) if w != right]
    if n:
        wrong = wrong[:n - 1]
    allo = wrong + [right]
    if shuffle:
        rng.shuffle(allo)
    return "Options:\n" + "\n".join(f"({LET[i]}) {o}" for i, o in enumerate(allo)), f"({LET[allo.index(right)]})"


# ------------------------------------------------------------------------------------------------ the kinds
def boolean_expressions(rng):
    def atom(d):
        r = rng.random()
        if d <= 0 or r < 0.45:
            return rng.choice(["True", "False"])
        if r < 0.75:
            return "not " + atom(d - 1)
        return "( " + expr(d - 1) + " )"

    def expr(d):
        parts = [atom(d)]
        for _ in range(rng.randint(1, 3)):
            parts += [rng.choice(["and", "or"]), atom(d)]
        return " ".join(parts)
    e = expr(rng.randint(1, 2))
    return e + " is", str(eval(e))


def date_understanding(rng):
    d0 = datetime.date(rng.randint(1905, 2030), rng.randint(1, 12), rng.randint(1, 28))
    fmt = lambda d: f"{d.month:02d}/{d.day:02d}/{d.year}"   # noqa: E731
    long = lambda d: d.strftime("%b %-d, %Y")                 # noqa: E731
    slash = lambda d: f"{d.month}/{d.day}/{d.year}"           # noqa: E731
    day = datetime.timedelta(days=1)
    who = rng.choice(PEOPLE[:20])
    kind = rng.randrange(12)
    if kind == 0:
        text, today = f"Today is {long(d0)}.", d0
    elif kind == 1:
        text, today = f"Yesterday was {long(d0)}.", d0 + day
    elif kind == 2:
        k = rng.randint(2, 9)
        text, today = f"The deadline is {long(d0)}, which is {k} days away from now.", d0 - k * day
    elif kind == 3:
        k = rng.choice([2, 5, 10, 20])
        text, today = f"{long(d0)} is like yesterday to {who}, but that is actually {k} years ago.", d0.replace(year=d0.year + k)
    elif kind == 4:
        k = rng.randint(2, 6)
        text, today = f"{who} was born on {long(d0)}. Today is their {k}-year-old birthday.", d0.replace(year=d0.year + k)
    elif kind == 5:
        text, today = f"Tomorrow is {slash(d0)}.", d0 - day
    elif kind == 6:
        wrong_day = d0 - day
        text, today = (f"{who} thinks today is {slash(wrong_day)}, but today is in fact {d0.strftime('%b %-d')}, which is 1 day later."), d0
    elif kind == 7:
        text, today = f"It was {d0.strftime('%b. %-d')}, {d0.year} a week ago.", d0 + 7 * day
    elif kind == 8:
        k = rng.choice([24, 36, 48])
        ny = datetime.date(d0.year, 1, 1)
        text, today = f"{d0.year} is coming in {k} hours.", ny - datetime.timedelta(hours=k).days * day - (day if k == 36 else 0 * day)
    elif kind == 9:
        text, today = f"The concert was scheduled to be on {fmt(d0)}, but was delayed by one day to today.", d0 + day
    elif kind == 10:
        text, today = f"Today's meeting is rescheduled to 11 am tomorrow, {slash(d0)}.", d0 - day
    else:
        k = rng.randint(2, 5)
        text = (f"{who} got their job in {d0.year}. Today is their {k}-year work anniversary. They still remember that on "
                f"{d0.strftime('%b %-d')}, their second day at work, they spilled coffee on their laptop.")
        today = (d0 - day).replace(year=d0.year + k)
    q, delta = rng.choice([("What is the date today", 0), ("What is the date tomorrow", 1), ("What is the date yesterday", -1),
                           ("What is the date one week ago from today", -7), ("What is the date one week from today", 7),
                           ("What is the date 10 days ago", -10), ("What is the date 24 hours later", 1),
                           ("What is the date a month ago", "m"), ("What is the date one year ago from today", "y")])
    if delta == "m":
        ans = today.replace(year=today.year - (today.month == 1), month=12 if today.month == 1 else today.month - 1)
    elif delta == "y":
        ans = today.replace(year=today.year - 1)
    else:
        ans = today + delta * day
    wrong = {fmt(ans + x * day) for x in (1, -1, 7, -7, 30, -31, 365, -366, 2, -14)}
    wrong |= {fmt(ans.replace(year=ans.year + x)) for x in (-10, 1, -1, 47)}
    wrong |= {f"{ans.day:02d}/{ans.month:02d}/{ans.year}"} if ans.day <= 12 and ans.day != ans.month else set()
    wrong = rng.sample(sorted(wrong - {fmt(ans)}), 5)
    o, lab = opts(rng, fmt(ans), wrong)
    return f"{text} {q} in MM/DD/YYYY?\n{o}", lab


