def formal_fallacies(rng):
    """An argument with two or three premises over one-place properties; valid or not by checking every small model.
    About half of the arguments are valid."""
    tpl, things = rng.choice(FF_TOPICS)
    npred = rng.choice([3, 3, 4])
    keys = "FGHK"[:npred]
    P = dict(zip(keys, [tpl.format(x) for x in rng.sample(things, npred)]))
    bare = lambda t: t[2:] if t.startswith("a ") else t[3:] if t.startswith("an ") else t   # noqa: E731
    forms = {
        "all": lambda a, b: (rng.choice([f"everyone who is {P[a]} is {P[b]}, too", f"being {P[a]} is sufficient for being {P[b]}",
                                         f"every {bare(P[a])} is {P[b]}", f"being {P[b]} is necessary for being {P[a]}"]),
                             lambda m: all(x[b] for x in m if x[a])),
        "no": lambda a, b: (rng.choice([f"no {bare(P[a])} is {P[b]}", f"whoever is {P[a]} is not {P[b]}",
                                        f"being {P[a]} is sufficient for not being {P[b]}"]),
                            lambda m: not any(x[a] and x[b] for x in m)),
        "some": lambda a, b: (rng.choice([f"somebody is {P[a]} and {P[b]}", f"some {bare(P[a])} is {P[b]}"]),
                              lambda m: any(x[a] and x[b] for x in m)),
        "somenot": lambda a, b: (rng.choice([f"not every {bare(P[a])} is {P[b]}", f"some {bare(P[a])} is not {P[b]}"]),
                                 lambda m: any(x[a] and not x[b] for x in m)),
        "allnot_or": lambda a, b: (f"everyone who is not {P[a]} is {P[b]}", lambda m: all(x[b] for x in m if not x[a])),
    }
    kinds = list(forms)
    models = []
    for size in (1, 2, 3):
        for combo in itertools.product(itertools.product([False, True], repeat=npred), repeat=size):
            models.append([dict(zip(keys, x)) for x in combo])
    want_valid = rng.random() < 0.5
    for _ in range(4000):
        npr = rng.choice([2, 2, 3])
        pr = [(rng.choice(kinds), *rng.sample(keys, 2)) for _ in range(npr)]
        co = (rng.choice(kinds[:4]), *rng.sample(keys, 2))
        if len({(p[1], p[2]) for p in pr + [co]}) < npr + 1 or (co[1], co[2]) in {(p[1], p[2]) for p in pr}:
            continue
        s_ = [forms[k](a, b) for k, a, b in pr + [co]]
        sat = [m for m in models if all(x[1](m) for x in s_[:-1])]
        if not sat:
            continue
        valid = all(s_[-1][1](m) for m in sat)
        if valid == want_valid:
            break
    cap = lambda t: t[0].upper() + t[1:]   # noqa: E731
    lead = ["First of all", "Next", "Plus"] if rng.random() < 0.5 else ["To begin with", "Moreover", "Finally"]
    prem = " ".join(f"{lead[i]}, {s_[i][0]}." for i in range(len(s_) - 1))
    concl = rng.choice([f"So, necessarily, {s_[-1][0]}.", f"We may conclude that {s_[-1][0]}.", f"Hence, {s_[-1][0]}.",
                        f"{cap('it follows that ' + s_[-1][0])}."])
    opening = rng.choice(['"Here comes a perfectly valid argument: ', '"It is not always easy to see who is related to whom, or what '
                          'belongs where. The following argument pertains to this question: ',
                          '"Some claims are easy to check and others are not. The following argument seeks to clarify some relations: '])
    return (f'{opening}{prem} {concl}"\nIs the argument, given the explicitly stated premises, deductively valid or invalid?'
            f"\nOptions:\n- valid \n- invalid", "valid" if valid else "invalid")


SHAPES = ["circle", "heptagon", "hexagon", "kite", "line", "octagon", "pentagon", "rectangle", "sector", "triangle"]


def geometric_shapes(rng):
    shape = rng.choice(SHAPES)
    cx, cy, r = rng.uniform(20, 80), rng.uniform(20, 80), rng.uniform(8, 30)
    f = lambda p: f"{p[0]:.2f},{p[1]:.2f}"   # noqa: E731
    rot = rng.uniform(0, 2 * math.pi)

    def poly(n):
        ang = sorted(rng.uniform(0, 2 * math.pi) for _ in range(n))
        if min((ang[(i + 1) % n] - ang[i]) % (2 * math.pi) for i in range(n)) < 0.35:
            ang = [rot + 2 * math.pi * i / n + rng.uniform(-0.25, 0.25) for i in range(n)]
        return [(cx + r * math.cos(a), cy + r * math.sin(a)) for a in ang]
    n = {"triangle": 3, "pentagon": 5, "hexagon": 6, "heptagon": 7, "octagon": 8}.get(shape)
    if n:
        pts = poly(n)
    elif shape == "line":
        pts = [(cx, cy), (cx + r * math.cos(rot), cy + r * math.sin(rot))]
    elif shape == "rectangle":
        w, h = r, r * rng.uniform(0.3, 0.8)
        c, s_ = math.cos(rot), math.sin(rot)
        pts = [(cx + x * c - y * s_, cy + x * s_ + y * c) for x, y in ((-w, -h), (w, -h), (w, h), (-w, h))]
    elif shape == "kite":
        a, b, w = r * rng.uniform(0.3, 0.6), r * rng.uniform(1.0, 1.5), r * rng.uniform(0.4, 0.8)
        c, s_ = math.cos(rot), math.sin(rot)
        pts = [(cx + x * c - y * s_, cy + x * s_ + y * c) for x, y in ((0, -a), (w, 0), (0, b), (-w, 0))]
    if shape == "circle":
        p0, p1 = (cx - r, cy), (cx + r, cy)
        d = f"M {f(p0)} A {r:.2f},{r:.2f} 0 1,0 {f(p1)} A {r:.2f},{r:.2f} 0 1,0 {f(p0)}"
    elif shape == "sector":
        a0, a1 = rot, rot + rng.uniform(0.6, 2.2)
        p0, p1 = (cx + r * math.cos(a0), cy + r * math.sin(a0)), (cx + r * math.cos(a1), cy + r * math.sin(a1))
        d = f"M {f((cx, cy))} L {f(p0)} A {r:.2f},{r:.2f} 0 0,1 {f(p1)} L {f((cx, cy))}"
    elif shape == "line":
        d = f"M {f(pts[0])} L {f(pts[1])}"
    else:
        if rng.random() < 0.3:      # two sub-paths, as some drawings come
            k = rng.randint(1, len(pts) - 1)
            d = ("M " + " L ".join(f(p) for p in pts[:k + 1]) + " M " + " L ".join(f(p) for p in pts[k:] + pts[:1]))
        else:
            d = "M " + " L ".join(f(p) for p in pts + pts[:1])
    names = sorted(SHAPES) if rng.random() < 0.5 else sorted(SHAPES + ["trapezoid"], key=lambda x: (x == "trapezoid", x))
    block = "Options:\n" + "\n".join(f"({LET[i]}) {o}" for i, o in enumerate(names))
    return f'This SVG path element <path d="{d}"/> draws a\n{block}', f"({LET[names.index(shape)]})"


