def widen():
    """Add the wider word lists to the generator's own (training puzzles; the first puzzles keep the short lists)."""
    global ADJ, NOUNS, WORDS
    if getattr(widen, "done", False):
        return
    widen.done = True
    ADJ = [(name, ws + dict(ADJ_MORE)[name]) for name, ws in ADJ]
    NOUNS = NOUNS + NOUNS_MORE
    WORDS = sorted(set(WORDS) | set(WORDS_MORE))


def hyperbaton(rng):
    k = rng.randint(3, 6)
    cats = sorted(rng.sample(range(len(ADJ)), k))
    adj = [rng.choice(ADJ[c][1]) for c in cats]
    noun = rng.choice(NOUNS)
    good = " ".join(adj + [noun])
    while True:
        p = adj[:]
        rng.shuffle(p)
        if p != adj:
            break
    bad = " ".join(p + [noun])
    pair = [good, bad] if rng.random() < 0.5 else [bad, good]
    return (f"Which sentence has the correct adjective order:\nOptions:\n(A) {pair[0]}\n(B) {pair[1]}", f"({LET[pair.index(good)]})")


