ORD = ["", "", "second", "third", "fourth", "fifth", "sixth"]


def _logical(n):
    def gen(rng):
        intro, pool, art, (lt, gt), (first, last), suf_f, suf_l = rng.choice(LD)
        items = rng.sample(pool, n)
        bare = [re.sub(r"^(a|an) ", "", x) for x in items]
        nm = lambda i: (f"{art} {bare[i]}" if art else bare[i]).strip()   # noqa: E731
        cap = lambda t: t[0].upper() + t[1:]                               # noqa: E731
        verb = "are" if bare[0].endswith("s") and art == "the" and "fruit" in intro else "is"
        order = list(range(n))
        rng.shuffle(order)                      # order[p] = the item at position p (0 = first / leftmost / cheapest / oldest)
        pos = {it: p for p, it in enumerate(order)}

        def where(p):
            if p == 0:
                return f"the {first}" if not (first == "first") else "first"
            if p == n - 1:
                return f"the {last}" if not (last == "last") else "last"
            if p < n / 2:
                return (f"the {ORD[p + 1]} {suf_f}" if suf_f.startswith("from") else f"the {ORD[p + 1]}{suf_f}") if suf_f else ORD[p + 1]
            q = n - p
            return f"the {ORD[q]} {suf_l}" if suf_l.startswith("from") else (f"the {ORD[q]}{suf_l}" if suf_l != "-to-last" else f"{ORD[q]}-to-last")

        def fits(perm, st):
            pp = {it: p for p, it in enumerate(perm)}
            return (pp[st[1]] < pp[st[2]]) if st[0] == "lt" else (pp[st[1]] == st[2])
        cands = [("lt", a, b) for a in range(n) for b in range(n) if pos[a] < pos[b]] + [("at", a, pos[a]) for a in range(n)]
        rng.shuffle(cands)
        chosen, left = [], list(itertools.permutations(range(n)))
        for st in cands:
            new = [p for p in left if fits(p, st)]
            if len(new) < len(left):
                chosen.append(st)
                left = new
            if len(left) == 1:
                break
        sents = []
        for st in chosen:
            if st[0] == "lt":
                a, b = (st[1], st[2]) if rng.random() < 0.5 else (st[2], st[1])
                rel = lt if pos[a] < pos[b] else gt
                if "finished" in rel:
                    sents.append(f"{cap(nm(a))} {rel} {nm(b)}.")
                else:
                    sents.append(f"{cap(nm(a))} {verb} {rel} {nm(b)}.")
            else:
                w = where(st[2])
                sents.append(f"{cap(nm(st[1]))} finished {w}." if "finished" in lt else f"{cap(nm(st[1]))} {verb} {w}.")
        qp = rng.randrange(n)
        w = where(qp)
        lines = [(f"{cap(nm(i))} finished {w}" if "finished" in lt else f"{cap(nm(i))} {verb} {w}") for i in range(n)]
        block = "Options:\n" + "\n".join(f"({LET[i]}) {x}" for i, x in enumerate(lines))
        word = {3: "three", 5: "five", 7: "seven"}[n]
        head = (f"The following paragraphs each describe a set of {word} objects arranged in a fixed order. The statements are "
                f"logically consistent within each paragraph. {intro.format(n=word, items=', '.join(items[:-1]) + ', and ' + items[-1])} ")
        return head + " ".join(sents) + "\n" + block, f"({LET[order[qp]]})"
    return gen


def multistep_arithmetic_two(rng):
    def grp():
        t = [str(rng.randint(-9, 9))]
        for _ in range(3):
            t += [rng.choice("+-*"), str(rng.randint(-9, 9))]
        return " ".join(t)
    e = f"(({grp()}) {rng.choice('+-*')} ({grp()}))"
    return e + " =", str(eval(e))


def navigate(rng):
    if rng.random() < 0.5:
        steps, x, y = [], 0, 0
        for _ in range(rng.randint(3, 8)):
            k, d = rng.randint(1, 10), rng.choice(["left", "right", "forward", "backward"])
            x += k * {"left": -1, "right": 1}.get(d, 0)
            y += k * {"forward": 1, "backward": -1}.get(d, 0)
            steps.append(f"Take {k} step{'s' if k > 1 else ''} {d}.")
        if (x, y) != (0, 0) and rng.random() < 0.5:           # close the walk so that both answers are common
            if x:
                steps.append(f"Take {abs(x)} step{'s' if abs(x) > 1 else ''} {'left' if x > 0 else 'right'}.")
            if y:
                steps.append(f"Take {abs(y)} step{'s' if abs(y) > 1 else ''} {'backward' if y > 0 else 'forward'}.")
            x = y = 0
        body = "Always face forward. " + " ".join(steps)
    else:
        steps, x, y, h = [], 0, 0, 0
        D = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for _ in range(rng.randint(3, 9)):
            r = rng.random()
            if r < 0.6:
                k = rng.randint(1, 10)
                x, y = x + k * D[h][0], y + k * D[h][1]
                steps.append(f"Take {k} step{'s' if k > 1 else ''}.")
            else:
                t = rng.choice(["Turn left.", "Turn right.", "Turn around."])
                h = (h + {"Turn left.": 3, "Turn right.": 1, "Turn around.": 2}[t]) % 4
                steps.append(t)
        if (x, y) != (0, 0) and rng.random() < 0.45 and (x == 0 or y == 0):
            want = 0 if y < 0 else 2 if y > 0 else 1 if x < 0 else 3
            turn = (want - h) % 4
            if turn:
                steps.append({1: "Turn right.", 2: "Turn around.", 3: "Turn left."}[turn])
            k = abs(x) + abs(y)
            steps.append(f"Take {k} step{'s' if k > 1 else ''}.")
            x = y = 0
        body = " ".join(steps)
    return (f"If you follow these instructions, do you return to the starting point? {body}\nOptions:\n- Yes\n- No",
            "Yes" if (x, y) == (0, 0) else "No")


OC = {"fruits": "apple banana peach plum grape orange strawberry raspberry blackberry nectarine".split(),
      "vegetables": "carrot potato onion cabbage yam garlic cauliflower lettuce head stalk of celery head of broccoli".split(),
      "animals": "cow dog cat pig goat horse rabbit mouse snake duck chicken bear frog fish donkey snail".split(),
      "musical instruments": "violin piano trumpet flute drum clarinet trombone accordion harmonica saxophone".split(),
      "objects": "chair table lamp bed couch toaster oven stove fridge microwave car".split()}
OC["vegetables"] = ["carrot", "potato", "onion", "cabbage", "yam", "garlic", "cauliflower", "lettuce head", "stalk of celery", "head of broccoli"]
NUMW = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"]


def _plural(w):
    if " of " in w:
        a, b = w.split(" of ", 1)
        return _plural(a) + " of " + b
    if w == "lettuce head":
        return "lettuce heads"
    if w in ("fish",):
        return w
    if w == "mouse":
        return "mice"
    if w.endswith("y") and w[-2] not in "aeiou":
        return w[:-1] + "ies"
    return w + ("es" if w.endswith(("ch", "sh", "s", "x", "o")) and w not in ("piano",) else "s")


def object_counting(rng):
    cat = rng.choice(list(OC))
    other = rng.choice([c for c in OC if c != cat and c != "objects"]) if cat != "objects" and rng.random() < 0.5 else None
    items = [(w, True) for w in rng.sample(OC[cat], rng.randint(3, min(8, len(OC[cat]))))]
    if other:
        items += [(w, False) for w in rng.sample(OC[other], rng.randint(1, 3))]
    rng.shuffle(items)
    total, parts = 0, []
    for w, ok in items:
        k = rng.choice([1, 1, 1, 2, 3, 4, 5])
        total += k * ok
        parts.append((f"{'an' if w[0] in 'aeiou' else 'a'} {w}") if k == 1 else f"{NUMW[k]} {_plural(w)}")
    lst = ", ".join(parts[:-1]) + ", and " + parts[-1]
    return f"I have {lst}. How many {cat} do I have?", str(total)


def penguins_in_a_table(rng):
    names = rng.sample(["Louis", "Bernard", "Vincent", "Gwen", "James", "Odette", "Marcel", "Colette", "Hugo"], 5)
    ages = rng.sample(range(2, 14), 5)
    hts = rng.sample(range(40, 100, 5), 5)
    wts = rng.sample(range(8, 22), 5)
    rows = list(zip(names, ages, hts, wts))
    base, extra = rows[:4], rows[4]
    head = ("Here is a table where the first line is a header and each subsequent line is a penguin:  name, age, height (cm), "
            "weight (kg) " + " ".join(f"{n}, {a}, {h}, {w}" for n, a, h, w in base) +
            f"  For example: the age of {base[0][0]} is {base[0][1]}, the weight of {base[3][0]} is {base[3][3]} kg, the height of "
            f"{base[1][0]} is {base[1][2]} cm.  ")
    cur = list(base)
    mode = rng.randrange(4)
    giraffes = None
    if mode == 1:
        cur.append(extra)
        head += f"We now add a penguin to the table:\n{extra[0]}, {extra[1]}, {extra[2]}, {extra[3]}\n"
    elif mode == 2:
        gone = rng.choice(cur)
        cur.remove(gone)
        head += f"We then delete the penguin named {gone[0]} from the table.\n"
    elif mode == 3:
        gn = rng.sample(["Jody", "Gladys", "Marian", "Donna", "Sabine", "Therese"], 4)
        giraffes = list(zip(gn, rng.sample(range(2, 14), 4), rng.sample(range(300, 460, 10), 4), rng.sample(range(400, 680, 10), 4)))
        head += ("And here is a similar table, but listing giraffes:\nname, age, height (cm), weight (kg)\n" +
                 "\n".join(f"{n}, {a}, {h}, {w}" for n, a, h, w in giraffes) + "\n")
    num = lambda cnt: ("Options:\n" + "\n".join(f"({LET[i]}) {x}" for i, x in enumerate(["1", "2", "3", "4", "5"])), f"({LET[cnt - 1]})")   # noqa: E731
    pool = sorted({r[0] for r in rows}, key=names.index)
    nam = lambda best: ("Options:\n" + "\n".join(f"({LET[i]}) {x}" for i, x in enumerate(pool)), f"({LET[pool.index(best)]})")   # noqa: E731
    for _ in range(50):
        q = rng.randrange(10)
        if q < 4:
            col, word, pick = [(1, "oldest", max), (1, "youngest", min), (2, "tallest", max), (2, "shortest", min)][q]
            o, lab = nam(pick(cur, key=lambda r: r[col])[0])
            return f"{head}Which is the {word} penguin?\n{o}", lab
        if q == 4:
            thr = rng.choice(sorted(r[1] for r in cur))
            cnt = sum(r[1] > thr for r in cur)
            if 1 <= cnt <= 5:
                o, lab = num(cnt)
                return f"{head}How many penguins are more than {thr} years old?\n{o}", lab
        if q == 5:
            thr = rng.choice(sorted(r[1] for r in cur))
            cnt = sum(r[1] < thr for r in cur)
            if 1 <= cnt <= 5:
                o, lab = num(cnt)
                return f"{head}How many penguins are less than {thr} years old?\n{o}", lab
        if q == 6:
            a, w = rng.choice(sorted(r[1] for r in cur)), rng.choice(sorted(r[3] for r in cur))
            cnt = sum(r[1] > a and r[3] > w for r in cur)
            if 1 <= cnt <= 5:
                o, lab = num(cnt)
                return f"{head}How many penguins are more than {a} years old and weight more than {w} kg?\n{o}", lab
        if q == 7:
            o, lab = nam(sorted(r[0] for r in cur)[-1])
            return f"{head}What is the name of the last penguin sorted by alphabetic order?\n{o}", lab
        if q == 8:
            r = rng.choice(cur)
            o, lab = nam(r[0])
            return f"{head}What is the name of the penguin that is {r[2]} cm tall?\n{o}", lab
        if q == 9 and giraffes:
            tot = len(cur) + len(giraffes)
            allo = [str(x) for x in range(tot - 2, tot + 3)]
            o = "Options:\n" + "\n".join(f"({LET[i]}) {x}" for i, x in enumerate(allo))
            return f"{head}How many animals are listed in the tables?\n{o}", f"({LET[allo.index(str(tot))]})"
    o, lab = nam(max(cur, key=lambda r: r[1])[0])
    return f"{head}Which is the oldest penguin?\n{o}", lab


