def reasoning_about_colored_objects(rng):
    n = rng.randint(3, 6)
    things = rng.sample(THINGS, n)
    cols = rng.sample(COLORS, n)
    place = rng.choice(["On the floor", "On the table", "On the desk", "On the nightstand"])
    art = lambda c: "an" if c[0] in "aeiou" else "a"   # noqa: E731
    desc = [f"{art(c)} {c} {t}" for c, t in zip(cols, things)]
    lst = ", ".join(desc[:-1]) + ", and " + desc[-1]
    q = rng.randrange(4)
    copt = "Options:\n" + "\n".join(f"({LET[i]}) {c}" for i, c in enumerate(COLORS))
    nopt = "Options:\n" + "\n".join(f"({LET[i]}) {w}" for i, w in enumerate(NUMW[:7]))
    if q == 0:
        i = rng.randrange(n)
        return f"{place}, you see a bunch of things arranged in a row: {lst}. What is the color of the {things[i]}?\n{copt}", f"({LET[COLORS.index(cols[i])]})"
    if q == 1:
        i = rng.randrange(1, n)
        side = rng.choice(["left", "right"])
        j = i - 1 if side == "left" else (i + 1 if i + 1 < n else i - 1)
        side = "left" if j == i - 1 else "right"
        return (f"{place}, you see a bunch of things arranged in a row: {lst}. What is the color of the thing directly to the "
                f"{side} of the {cols[i]} thing?\n{copt}", f"({LET[COLORS.index(cols[j])]})")
    if q == 2:
        c = rng.choice(cols)
        cnt = sum(x != c for x in cols)
        return (f"{place}, you see {lst}. How many things are neither {c} nor {rng.choice([x for x in COLORS if x not in cols])}?\n{nopt}",
                f"({LET[cnt]})") if cnt <= 6 else reasoning_about_colored_objects(rng)
    i = rng.randrange(n)
    far = 0 if i >= n / 2 else n - 1
    if abs(i - 0) == abs(i - (n - 1)):
        return reasoning_about_colored_objects(rng)
    return (f"{place}, you see a bunch of things arranged in a row: {lst}. What is the color of the thing furthest from the "
            f"{cols[i]} thing?\n{copt}", f"({LET[COLORS.index(cols[far])]})")


