def temporal_sequences(rng):
    who = rng.choice(PEOPLE)
    place = rng.choice(PLACES)
    hours = sorted(rng.sample(range(5, 22), rng.randint(4, 6)))
    start, end = hours[0], hours[-1] + rng.randint(1, 2)
    cuts = hours + [end]
    hh = lambda h: f"{(h - 1) % 12 + 1}{'am' if h < 12 else 'pm'}"   # noqa: E731
    spans = [(cuts[i], cuts[i + 1]) for i in range(len(cuts) - 1)]
    free = rng.randrange(len(spans))
    seers = rng.sample([p for p in PEOPLE if p != who], len(spans))
    acts = rng.sample(SEEN, len(spans))
    lines = [f"{who} woke up at {hh(start)}."]
    for i, (a, b) in enumerate(spans):
        if i != free:
            lines.append(f"{seers[i]} saw {who} {acts[i]} from {hh(a)} to {hh(b)}.")
    lines.append(f"{place[0].upper() + place[1:]} was closed after {hh(end)}.")
    right = f"{hh(spans[free][0])} to {hh(spans[free][1])}"
    wrong = [f"{hh(a)} to {hh(b)}" for i, (a, b) in enumerate(spans) if i != free]
    o, lab = opts(rng, right, rng.sample(wrong, min(3, len(wrong))))
    return (f"Today, {who} went to {place}. Between what times could they have gone?\nWe know that:\n" + "\n".join(lines) +
            f"\nBetween what times could {who} have gone to {place}?\n{o}", lab)


