def _tracking(n):
    def gen(rng):
        intro, verb, pool, mid, swap, endq = rng.choice(TS)
        who = NAMES[:n]
        things = rng.sample(pool, n)
        has = dict(zip(who, things))
        vb = lambda t: (verb[:-2] + (" an" if t[0] in "aeiou" else " a")) if verb.endswith(" a") else verb   # noqa: E731
        start = ", ".join(f"{w} {vb(t)} {t}" for w, t in list(has.items())[:-1]) + f", and {who[-1]} {vb(things[-1])} {things[-1]}"
        k = n if n > 3 else 3
        ops = []
        for i in range(k):
            a, b = rng.sample(who, 2)
            has[a], has[b] = has[b], has[a]
            ops.append(f"{'First' if i == 0 else 'Finally' if i == k - 1 else 'Then'}, {a} and {b} {swap}.")
        target = rng.choice(who)
        strip = lambda t: re.sub(r" (ball|present)$", "", t) if endq.endswith("has the") else t   # noqa: E731
        show = [strip(t) for t in things]
        block = "Options:\n" + "\n".join(f"({LET[i]}) {t}" for i, t in enumerate(show))
        names = ", ".join(who[:-1]) + ", and " + who[-1]
        return (f"{names} {intro}: {start}.\n{mid} {' '.join(ops)} {endq.format(target)}\n{block}",
                f"({LET[things.index(has[target])]})")
    return gen


def web_of_lies(rng):
    k = rng.randint(4, 6)
    ppl = rng.sample(PEOPLE, k)
    truth = [rng.random() < 0.5]
    sents = [f"{ppl[0]} {'tells the truth' if truth[0] else 'lies'}."]
    for i in range(1, k):
        says_truth = rng.random() < 0.5          # what person i says about person i-1
        truth.append(says_truth == truth[i - 1])
        sents.append(f"{ppl[i]} says {ppl[i - 1]} {'tells the truth' if says_truth else 'lies'}.")
    return f"Question: {' '.join(sents)} Does {ppl[-1]} tell the truth?", "Yes" if truth[-1] else "No"


def word_sorting(rng):
    ws = rng.sample(WORDS, rng.randint(4, 18))
    return "Sort the following words alphabetically: List: " + " ".join(ws), " ".join(sorted(ws))


