    ap.add_argument("--prefix", default="pz")
    ap.add_argument("--fingerprints")
    ap.add_argument("--exclude", nargs="*", default=[])
    ap.add_argument("--kinds", help="comma list of kinds (default: all 19)")
    ap.add_argument("--vocab", choices=("first", "wide"), default="first", help="wide: adjective and word lists with the extra words")
    a = ap.parse_args()
    if a.vocab == "wide":
        widen()
    banned = set()
    if a.fingerprints == "toolkit":
        from wsp import data  # noqa: PLC0415
        banned = set(data.bench_fingerprints())
    elif a.fingerprints:
        banned = set(open(a.fingerprints).read().split())
    for path in a.exclude:
        banned |= {fingerprint(json.loads(x)["problem"]) for x in open(path) if x.strip()}
    rows, dropped = make(a.per_task, a.seed, a.prefix, banned, a.kinds.split(",") if a.kinds else None)
    with open(a.out, "w") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    import collections
    c = collections.Counter(r["subject"] for r in rows)
    print(f"{len(rows)} puzzles of {len(c)} kinds ({min(c.values())}-{max(c.values())} each); dropped (a shipped fingerprint or an excluded file): {dropped}")
